func findRHS(node ast.Node) []string {
	var rhs []string

	if node == nil {
		return rhs
	}

	switch t := node.(type) {
	case *ast.BasicLit, *ast.SelectStmt, *ast.ChanType,
		*ast.LabeledStmt, *ast.DeclStmt, *ast.BranchStmt,
		*ast.TypeSpec, *ast.ArrayType, *ast.CaseClause,
		*ast.CommClause, *ast.KeyValueExpr, *ast.MapType,
		*ast.FuncLit:
		// Nothing to add to RHS
	case *ast.Ident:
		return []string{t.Name}
	case *ast.SelectorExpr:
		rhs = findRHS(t.X)
		rhs = append(rhs, findRHS(t.Sel)...)
	case *ast.AssignStmt:
		for _, v := range t.Rhs {
			rhs = append(rhs, findRHS(v)...)
		}
	case *ast.CallExpr:
		for _, v := range t.Args {
			rhs = append(rhs, findRHS(v)...)
		}
		rhs = append(rhs, findRHS(t.Fun)...)
	case *ast.CompositeLit:
		for _, v := range t.Elts {
			rhs = append(rhs, findRHS(v)...)
		}
	case *ast.IfStmt:
		rhs = append(rhs, findRHS(t.Cond)...)
		rhs = append(rhs, findRHS(t.Init)...)
	case *ast.BinaryExpr:
		return append(
			findRHS(t.X),
			findRHS(t.Y)...,
		)
	case *ast.TypeSwitchStmt:
		return findRHS(t.Assign)
	case *ast.ReturnStmt:
		for _, v := range t.Results {
			rhs = append(rhs, findRHS(v)...)
		}
	case *ast.BlockStmt:
		for _, v := range t.List {
			rhs = append(rhs, findRHS(v)...)
		}
	case *ast.SwitchStmt:
		return findRHS(t.Tag)
	case *ast.GoStmt:
		return findRHS(t.Call)
	case *ast.ForStmt:
		return findRHS(t.Cond)
	case *ast.DeferStmt:
		return findRHS(t.Call)
	case *ast.SendStmt:
		// Not implementing for this test
	case *ast.IndexExpr:
		rhs = append(rhs, findRHS(t.Index)...)
		rhs = append(rhs, findRHS(t.X)...)
	case *ast.SliceExpr:
		rhs = append(rhs, findRHS(t.X)...)
		rhs = append(rhs, findRHS(t.Low)...)
		rhs = append(rhs, findRHS(t.High)...)
	default:
		fmt.Printf("Unknown type: %T\n", t)
	}

	return rhs
}

func findLHS(node ast.Node) []string {
	var lhs []string

	if node == nil {
		return lhs
	}

	switch t := node.(type) {
	case *ast.AssignStmt:
		for _, v := range t.Lhs {
			lhs = append(lhs, findLHS(v)...)
		}
	case *ast.Ident:
		return []string{t.Name}
	case *ast.SelectorExpr:
		return findLHS(t.X)
	case *ast.KeyValueExpr:
		lhs = append(lhs, findLHS(t.Key)...)
		lhs = append(lhs, findLHS(t.Value)...)
	default:
		fmt.Printf("Unknown LHS type: %T\n", t)
	}

	return lhs
}

